1	// Package calibrate 是本地器具校准与证书的本地台账。
2	//
3	// 台账只保存在本机指定文件中，不连接任何真实实验室。多次打开同一文件
4	// 可以继续查询与操作，不同文件之间的数据互不相干。
5	package calibrate
6	
7	import (
8		"encoding/json"
9		"errors"
10		"fmt"
11		"math"
12		"os"
13		"path/filepath"
14		"sort"
15		"strings"
16		"time"
17	)
18	
19	// 日期布局，所有入参日期都必须是实际存在的 YYYY-MM-DD。
20	const DateLayout = "2006-01-02"
21	
22	// Status 是器具的运行状态。
23	type Status string
24	
25	const (
26		// StatusPending 表示待校准，新登记器具的初始状态。
27		StatusPending Status = "待校准"
28		// StatusInUse 表示在用；在用本身不代表已经校准。
29		StatusInUse Status = "在用"
30		// StatusRetired 表示停用；停用不删除证书与使用记录。
31		StatusRetired Status = "停用"
32	)
33	
34	// ParseStatus 把命令行或文件中的状态文本解析为 Status。
35	func ParseStatus(s string) (Status, error) {
36		switch strings.TrimSpace(s) {
37		case string(StatusPending), "pending":
38			return StatusPending, nil
39		case string(StatusInUse), "in-use", "in_use":
40			return StatusInUse, nil
41		case string(StatusRetired), "retired":
42			return StatusRetired, nil
43		default:
44			return "", fmt.Errorf("无效状态 %q：只能是 在用、停用 或 待校准", s)
45		}
46	}
47	
48	// Instrument 是登记的器具信息。
49	type Instrument struct {
50		ID           string  `json:"id"`
51		Name         string  `json:"name"`
52		AllowedError float64 `json:"allowed_error"`
53		Status       Status  `json:"status"`
54		RegisteredAt string  `json:"registered_at"`
55	}
56	
57	// Certificate 是一张校准证书。
58	type Certificate struct {
59		Number       string  `json:"number"`
60		InstrumentID string  `json:"instrument_id"`
61		CalDate      string  `json:"cal_date"`
62		Expiry       string  `json:"expiry"`
63		Method       string  `json:"method"`
64		Error        float64 `json:"error"`
65		Summary      string  `json:"summary"`
66		CreatedAt    string  `json:"created_at"`
67	}
68	
69	// Pass 按证书自身数据判断是否合格：测得误差绝对值不超过允许误差（含限值）。
70	// 结论由数据计算，录入者不能自行选择。
71	func (c Certificate) Pass(allowedError float64) bool {
72		return math.Abs(c.Error) <= allowedError
73	}
74	
75	// UsageRecord 是一次使用申请的留痕，原因在申请发生时冻结。
76	type UsageRecord struct {
77		InstrumentID string   `json:"instrument_id"`
78		RequestedAt  string   `json:"requested_at"`
79		Allowed      bool     `json:"allowed"`
80		Reasons      []string `json:"reasons"`
81	}
82	
83	// ledgerData 是台账文件的持久化结构。
84	type ledgerData struct {
85		Version      int           `json:"version"`
86		Instruments  []Instrument  `json:"instruments"`
87		Certificates []Certificate `json:"certificates"`
88		Usage        []UsageRecord `json:"usage"`
89		Plans        []Plan        `json:"plans,omitempty"`
90	}
91	
92	// Ledger 是一份可操作的本地台账。
93	type Ledger struct {
94		path string
95		now  func() time.Time
96		data ledgerData
97	}
98	
99	// ValidationError 表示输入未通过业务校验，调用方不会改动任何已有记录。
100	type ValidationError struct{ Msg string }
101	
102	func (e *ValidationError) Error() string { return e.Msg }
103	
104	func validationError(format string, args ...any) error {
105		return &ValidationError{Msg: fmt.Sprintf(format, args...)}
106	}
107	
108	// IsValidation 报告 err 是否为业务校验错误。
109	func IsValidation(err error) bool {
110		var v *ValidationError
111		return errors.As(err, &v)
112	}
113	
114	// ConflictError 表示同号证书内容不一致等冲突，已有数据保持不变。
115	type ConflictError struct{ Msg string }
116	
117	func (e *ConflictError) Error() string { return e.Msg }
118	
119	// IsConflict 报告 err 是否为冲突错误。
120	func IsConflict(err error) bool {
121		var c *ConflictError
122		return errors.As(err, &c)
123	}
124	
125	// ErrNotFound 表示编号在台账中不存在。
126	var ErrNotFound = errors.New("记录不存在")
127	
128	func cleanText(s string) (string, error) {
129		t := strings.TrimSpace(s)
130		if t == "" {
131			return "", validationError("不能留空或只有空白")
132		}
133		return t, nil
134	}
135	
136	func parseFiniteDate(s, field string) (time.Time, string, error) {
137		t := strings.TrimSpace(s)
138		if t == "" {
139			return time.Time{}, "", validationError("%s不能留空", field)
140		}
141		parsed, err := time.Parse(DateLayout, t)
142		if err != nil {
143			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
144		}
145		// time.Parse 对 YYYY-MM-DD 遇到超范围日期会直接报错；再用 Format
146		// 往返一次，拒绝 2024-2-3 之类格式不符的输入。
147		if parsed.Format(DateLayout) != t {
148			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
149		}
150		return parsed, t, nil
151	}
152	
153	func finiteNumber(v float64, field string) error {
154		if math.IsNaN(v) || math.IsInf(v, 0) {
155			return validationError("%s必须是有限数", field)
156		}
157		return nil
158	}
159	
160	// Open 打开 path 所指的本机台账；文件不存在时建立一份新台账。
161	// 同一文件可以反复打开继续操作，不同 path 的数据互不混入。
162	func Open(path string) (*Ledger, error) {
163		return openAt(path, time.Now)
164	}
165	
166	func openAt(path string, now func() time.Time) (*Ledger, error) {
167		if strings.TrimSpace(path) == "" {
168			return nil, fmt.Errorf("台账文件路径不能为空")
169		}
170		l := &Ledger{
171			path: path,
172			now:  now,
173			data: ledgerData{Version: 1},
174		}
175		raw, err := os.ReadFile(path)
176		if err != nil {
177			if errors.Is(err, os.ErrNotExist) {
178				return l, nil
179			}
180			return nil, fmt.Errorf("读取台账 %s: %w", path, err)
181		}
182		if len(raw) > 0 {
183			if err := json.Unmarshal(raw, &l.data); err != nil {
184				return nil, fmt.Errorf("台账文件 %s 已损坏: %w", path, err)
185			}
186		}
187		if l.data.Version == 0 {
188			l.data.Version = 1
189		}
190		return l, nil
191	}
192	
193	// Path 返回台账文件位置。
194	func (l *Ledger) Path() string { return l.path }
195	
196	// save 把当前台账完整写回文件：先写临时文件再原子改名，
197	// 保证无效录入中断时不会留下半份记录。
198	func (l *Ledger) save() error {
199		if err := os.MkdirAll(filepath.Dir(l.path), 0o755); err != nil {
200			return fmt.Errorf("写入台账文件 %s 前创建目录失败: %w", l.path, err)
201		}
202		raw, err := json.MarshalIndent(l.data, "", "  ")
203		if err != nil {
204			return fmt.Errorf("序列化台账 %s: %w", l.path, err)
205		}
206		raw = append(raw, '\n')
207		tmp, err := os.CreateTemp(filepath.Dir(l.path), ".ledger-*.tmp")
208		if err != nil {
209			return fmt.Errorf("为台账 %s 创建临时文件: %w", l.path, err)
210		}
211		tmpName := tmp.Name()
212		defer os.Remove(tmpName)
213		if _, err := tmp.Write(raw); err != nil {
214			tmp.Close()
215			return fmt.Errorf("写入台账 %s 的临时文件: %w", l.path, err)
216		}
217		if err := tmp.Close(); err != nil {
218			return fmt.Errorf("关闭台账 %s 的临时文件: %w", l.path, err)
219		}
220		if err := os.Rename(tmpName, l.path); err != nil {
221			return fmt.Errorf("替换台账文件 %s: %w", l.path, err)
222		}
223		return nil
224	}
225	
226	func (l *Ledger) findInstrument(id string) *Instrument {
227		for i := range l.data.Instruments {
228			if l.data.Instruments[i].ID == id {
229				return &l.data.Instruments[i]
230			}
231		}
232		return nil
233	}
234	
235	// Instrument 按编号返回登记器具的独立副本；编号不存在时返回包装了
236	// ErrNotFound 的错误。它只读取该器具自身的登记信息，不组装历史证书、
237	// 使用拒绝记录或校准计划：显示一张证书的结论只需要证书自身的测得误差
238	// 与该器具登记的允许误差，不需要完整核对结果。
239	func (l *Ledger) Instrument(id string) (*Instrument, error) {
240		inst := l.findInstrument(id)
241		if inst == nil {
242			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
243		}
244		saved := *inst
245		return &saved, nil
246	}
247	
248	func (l *Ledger) findCertificate(number string) *Certificate {
249		for i := range l.data.Certificates {
250			if l.data.Certificates[i].Number == number {
251				return &l.data.Certificates[i]
252			}
253		}
254		return nil
255	}
256	
257	// RegisterInput 是登记器具的输入。
258	type RegisterInput struct {
259		ID           string
260		Name         string
261		AllowedError float64
262	}
263	
264	// saveInstruments 是器具登记与状态切换共用的一条规则：只有本次保存成功，
265	// 器具信息的改动才算正式生效。它在整份器具切片的独立副本上暂存 change 对
266	// 器具信息的修改（新增器具或改动已有器具字段都一样），只有原子替换台账文件
267	// 成功后才提交；写盘失败时恢复原切片并明确返回保存错误，保证同一台账对象
268	// 随后的列出、按编号核对、编号占用判断、待办与使用资格判断都与修改前完全
269	// 一致——失败的新器具或目标状态既不会提前生效或占用编号，也不会在此后其他
270	// 成功操作写盘时被顺带写入。保存成功后返回 id 指定器具已保存内容的独立展示
271	// 副本：调用方改动这份结果不能改写正式台账。
272	//
273	// 调用方必须先完成全部业务校验再进入这里：重复编号、非法状态或未知器具等
274	// 未通过业务校验的申请按原有原因拒绝，不会走到写盘而被混成保存失败；目标
275	// 状态本来就与正式状态相同这类无需改动的情形，也由调用方在进入前直接成功
276	// 跳过，不额外写盘。
277	func (l *Ledger) saveInstruments(id string, change func(*[]Instrument)) (*Instrument, error) {
278		original := l.data.Instruments
279		// 独立副本与原切片不共享底层数组：change 的暂存修改不会提前渗进正式
280		// 台账，写盘失败时恢复原切片即可。
281		staged := make([]Instrument, len(original))
282		copy(staged, original)
283		change(&staged)
284		l.data.Instruments = staged
285		if err := l.save(); err != nil {
286			l.data.Instruments = original
287			return nil, err
288		}
289		saved := *l.findInstrument(id)
290		return &saved, nil
291	}
292	
293	// Register 登记一件新器具。编号、名称不得为空白，允许误差必须是不小于零的
294	// 有限数；编号重复或输入无效时明确拒绝，原记录不变。新器具处于待校准状态。
295	//
296	// 只有本次保存成功，新器具才算正式登记：若台账文件无法写入或替换，明确返回
297	// 保存错误而不返回已登记的器具，台账（含同一对象随后的列出、按编号核对、
298	// 编号占用判断以及校准与使用安排）与登记前完全一致——失败的器具不出现在列表、
299	// 不占用编号，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次
300	// 提交同号合法内容仍报保存错误（不会因内存里残留的失败器具而被当成编号重复）。
301	// 恢复可写后无需重新打开台账，重新提交且保存成功才新增一件待校准器具，
302	// 登记时间、名称与允许误差均取本次成功提交的内容，不沿用失败申请；成功后
303	// 再登记同号仍按编号唯一拒绝。未通过业务校验的申请仍按原有方式拒绝，
304	// 不会因台账不可写而被混成保存失败。
305	func (l *Ledger) Register(in RegisterInput) (*Instrument, error) {
306		id, err := cleanText(in.ID)
307		if err != nil {
308			return nil, fmt.Errorf("器具编号无效：%w", err)
309		}
310		name, err := cleanText(in.Name)
311		if err != nil {
312			return nil, fmt.Errorf("器具名称无效：%w", err)
313		}
314		if err := finiteNumber(in.AllowedError, "允许的绝对误差"); err != nil {
315			return nil, err
316		}
317		if in.AllowedError < 0 {
318			return nil, validationError("允许的绝对误差不能小于零")
319		}
320		if l.findInstrument(id) != nil {
321			return nil, validationError("器具编号 %s 已存在，编号必须唯一", id)
322		}
323		inst := Instrument{
324			ID:           id,
325			Name:         name,
326			AllowedError: in.AllowedError,
327			Status:       StatusPending,
328			RegisteredAt: l.now().Format(time.RFC3339),
329		}
330		// 在独立的新切片上暂存新器具：只有原子替换台账文件成功后才提交，
331		// 保存规则见 saveInstruments。
332		return l.saveInstruments(id, func(staged *[]Instrument) {
333			*staged = append(*staged, inst)
334		})
335	}
336	
337	// SetStatus 切换器具状态。切换为在用不代表已校准；停用不删除证书与使用记录。
338	//
339	// 目标状态合法且与最后成功保存的状态不同后才写盘：若台账文件无法写入或替换，
340	// 明确返回保存错误，台账（含同一对象随后的列出、按器具核对、待办与使用判断）
341	// 与切换前完全一致——器具仍保持最后成功保存的状态，失败的目标状态既不会提前
342	// 参与使用资格判断，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时
343	// 再次提交同一目标状态仍报保存错误（不会因内存已被改成目标状态而被当成
344	// “状态未变”跳过保存返回成功）。恢复可写后无需重新打开台账，重新提交且保存
345	// 成功，新状态才生效。请求状态本来就等于最后成功保存的状态时直接成功，不写盘。
346	func (l *Ledger) SetStatus(id string, status Status) error {
347		switch status {
348		case StatusInUse, StatusRetired, StatusPending:
349		default:
350			return validationError("无效状态：只能是 在用、停用 或 待校准")
351		}
352		inst := l.findInstrument(id)
353		if inst == nil {
354			return fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
355		}
356		if inst.Status == status {
357			return nil
358		}
359		// 在整份器具切片的独立副本上暂存新状态：只有原子替换台账文件成功后才
360		// 提交，保存规则见 saveInstruments。
361		_, err := l.saveInstruments(id, func(staged *[]Instrument) {
362			for i := range *staged {
363				if (*staged)[i].ID == id {
364					(*staged)[i].Status = status
365					break
366				}
367			}
368		})
369		return err
370	}
371	
372	// CertificateInput 是录入校准证书的输入。
373	type CertificateInput struct {
374		InstrumentID string
375		Number       string
376		CalDate      string
377		Expiry       string
378		Method       string
379		Error        float64
380		Summary      string
381	}
382	
383	// AddCertificate 录入一张校准证书并返回它；若同号证书且全部业务字段一致，
384	// 返回原证书且不增加历史（幂等）。同号内容不同报冲突且不改动已有数据。
385	//
386	// 同号判定优先于“校准日期不能晚于本机今天”：证书首次录入时内容合法且已
387	// 成功保存，之后本机调整时区或日期、使当前日历日期落到该证书校准日期
388	// 之前，再原样提交同号证书仍幂等成功并返回首次保存的原证书（保留首次
389	// 录入时间，不新增历史、不切换器具状态、不新增使用申请）；同号但修改了
390	// 校准方法、摘要或测得误差等任一字段时，仍报同号内容冲突而不是未来日期
391	// 错误，原证书不被覆盖。只有台账中不存在的新编号才受“校准日期不能晚于
392	// 本机今天”约束，本机日期正常推进时的新录入行为保持不变。
393	//
394	// 返回的证书只是本次已保存内容的展示副本，与台账内存储不共享内存：调用方
395	// 整理返回结果中的误差、截止日、编号或其他字段，不会改写台账里的正式证书，
396	// 不影响最近证书的选择、使用资格判断与编号占用，也不会被此后的写盘带入文件；
397	// 重新查询得到的仍是实际保存的内容。
398	//
399	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
400	// 台账（含同一对象随后的查询）与录入前完全一致——失败的证书既不进入历史、
401	// 不占用证书编号或该器具当天的位置，也不会在此后其他成功操作写盘时被顺带写入；
402	// 恢复可写后重新提交同号同内容会作为新证书正常录入。
403	func (l *Ledger) AddCertificate(in CertificateInput) (*Certificate, bool, error) {
404		instID, err := cleanText(in.InstrumentID)
405		if err != nil {
406			return nil, false, fmt.Errorf("器具编号无效：%w", err)
407		}
408		number, err := cleanText(in.Number)
409		if err != nil {
410			return nil, false, fmt.Errorf("证书编号无效：%w", err)
411		}
412		method, err := cleanText(in.Method)
413		if err != nil {
414			return nil, false, fmt.Errorf("校准方法无效：%w", err)
415		}
416		summary, err := cleanText(in.Summary)
417		if err != nil {
418			return nil, false, fmt.Errorf("摘要无效：%w", err)
419		}
420		if err := finiteNumber(in.Error, "测得误差"); err != nil {
421			return nil, false, err
422		}
423	
424		inst := l.findInstrument(instID)
425		if inst == nil {
426			return nil, false, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
427		}
428	
429		_, calText, err := parseFiniteDate(in.CalDate, "校准日期")
430		if err != nil {
431			return nil, false, err
432		}
433		_, expText, err := parseFiniteDate(in.Expiry, "有效期截止日")
434		if err != nil {
435			return nil, false, err
436		}
437		if expText <= calText {
438			return nil, false, validationError("有效期截止日 %s 必须晚于校准日期 %s", expText, calText)
439		}
440	
441		// 同号判定优先于“校准日期不能晚于本机今天”：证书首次保存时内容合法，
442		// 之后本机日期（含时区调整）回落到该证书校准日期之前，同号提交仍应按
443		// 已有证书处理——内容一致幂等返回原证书，内容不同报冲突；本机日期变化
444		// 不能让已有证书的重复提交变成一次失败的新录入。未来日期限制只约束
445		// 台账中不存在的新证书编号。
446		if existing := l.findCertificate(number); existing != nil {
447			same := existing.InstrumentID == instID &&
448				existing.CalDate == calText &&
449				existing.Expiry == expText &&
450				existing.Method == method &&
451				existing.Summary == summary &&
452				existing.Error == in.Error
453			if !same {
454				return nil, false, &ConflictError{Msg: fmt.Sprintf(
455					"证书编号 %s 已存在且内容不同，拒绝覆盖已有数据", number)}
456			}
457			// 同号且全部业务字段一致：返回原证书，不增加历史记录。
458			// 返回独立副本：调用方对返回结果的整理不能成为改写正式证书的途径。
459			dup := *existing
460			return &dup, true, nil
461		}
462	
463		// 与“本机今天”按日历日期比较，避免时分秒和时区造成边界误差。
464		// 新编号证书的校准日期晚于本机今天时直接拒绝：不新增证书，也不占用
465		// 该编号或该器具当天的位置。
466		todayText := l.now().Format(DateLayout)
467		if calText > todayText {
468			return nil, false, validationError("校准日期 %s 不能晚于本机今天 %s", calText, todayText)
469		}
470		// 同一器具同一天不接受两张不同编号的证书。
471		for i := range l.data.Certificates {
472			c := &l.data.Certificates[i]
473			if c.InstrumentID == instID && c.CalDate == calText {
474				return nil, false, validationError(
475					"器具 %s 在 %s 已有证书 %s，同一天不能再登记不同编号的证书",
476					instID, calText, c.Number)
477			}
478		}
479	
480		cert := Certificate{
481			Number:       number,
482			InstrumentID: instID,
483			CalDate:      calText,
484			Expiry:       expText,
485			Method:       method,
486			Error:        in.Error,
487			Summary:      summary,
488			CreatedAt:    l.now().Format(time.RFC3339),
489		}
490		// 在独立的新切片上暂存新证书：只有原子替换台账文件成功后才提交。
491		// 写盘失败时恢复原切片，保证同一台账对象随后看到的历史、最近证书、
492		// 证书编号占用与同日位置都与录入前一致，且不会被之后的写盘顺带写入。
493		original := l.data.Certificates
494		staged := make([]Certificate, 0, len(original)+1)
495		staged = append(staged, original...)
496		staged = append(staged, cert)
497		l.data.Certificates = staged
498		if err := l.save(); err != nil {
499			l.data.Certificates = original
500			return nil, false, err
501		}
502		// 返回已保存证书的独立副本：返回结果只表示本次保存的内容，调用方的
503		// 后续整理不会连带改写台账内的正式证书。
504		saved := *l.findCertificate(number)
505		return &saved, false, nil
506	}
507	
508	// certNewer 是“最近证书”的唯一先后规则：校准日期较新者在前，与录入先后、
509	// 到期先后或合格结论无关；校准日期相同时（正常业务下同器具同日只允许一张）
510	// 按证书编号升序，保证并列时结果稳定。
511	func certNewer(a, b Certificate) bool {
512		if a.CalDate != b.CalDate {
513			return a.CalDate > b.CalDate
514		}
515		return a.Number < b.Number
516	}
517	
518	// certificatesOf 收集并整理某器具的完整证书历史，按校准日期从新到旧排序。
519	// 只在确实需要完整历史的按器具核对中使用；只要最近证书的入口不应走这里，
520	// 避免为取一张证书而收集、排序整段历史。切片元素都是台账证书的独立副本。
521	func (l *Ledger) certificatesOf(id string) []Certificate {
522		var out []Certificate
523		for _, c := range l.data.Certificates {
524			if c.InstrumentID == id {
525				out = append(out, c)
526			}
527		}
528		sort.Slice(out, func(i, j int) bool { return certNewer(out[i], out[j]) })
529		return out
530	}
531	
532	// latestOf 从已按 certNewer 排好序的证书中取出最近证书的独立副本；
533	// 空切片返回 nil。
534	func latestOf(certs []Certificate) *Certificate {
535		if len(certs) == 0 {
536			return nil
537		}
538		latest := certs[0]
539		return &latest
540	}
541	
542	// latestCertificate 只扫描一遍该器具自身的证书挑出最近一张，不收集、不排序
543	// 完整历史：只查询最近证书或判断能否使用时，不必承担整理整段历史的工作。
544	// 归属过滤保证其他器具的证书既不会混入也不会影响本器具的最近证书选择。
545	// 返回的是独立副本，调用方的整理不会回写台账。
546	func (l *Ledger) latestCertificate(id string) *Certificate {
547		best := Certificate{}
548		found := false
549		for _, c := range l.data.Certificates {
550			if c.InstrumentID != id {
551				continue
552			}
553			if !found || certNewer(c, best) {
554				best = c
555				found = true
556			}
557		}
558		if !found {
559			return nil
560		}
561		latest := best
562		return &latest
563	}
564	
565	// LatestCertificate 返回器具按校准日期确定的最近证书；没有证书时返回 nil。
566	// 最近证书与录入先后、到期先后或合格结论无关，补录较早证书只增加历史、
567	// 不改变最近证书。它只挑出这一张证书，不组装完整历史；返回的是独立副本。
568	func (l *Ledger) LatestCertificate(id string) *Certificate {
569		return l.latestCertificate(id)
570	}
571	
572	// CertificateView 是证书及其在当前日期下的判定结果。
573	type CertificateView struct {
574		Certificate
575		Pass    bool `json:"pass"`
576		Expired bool `json:"expired"`
577	}
578	
579	func viewCertificate(c Certificate, allowed float64, today time.Time) CertificateView {
580		return CertificateView{
581			Certificate: c,
582			Pass:        c.Pass(allowed),
583			// 有效期截止日当天起即到期：按日历日期比较，今天 >= 截止日即为到期。
584			Expired: today.Format(DateLayout) >= c.Expiry,
585		}
586	}
587	
588	// UsageDecision 是一次使用申请的评估结果，原因在申请时冻结留痕。
589	type UsageDecision struct {
590		InstrumentID string
591		Allowed      bool
592		Reasons      []string
593		Latest       *CertificateView
594		evaluatedAt  time.Time
595	}
596	
597	// decideUsage 按器具状态与“最近证书”判定 today 所在本机日历日期能否使用，
598	// 并列出全部适用原因。最近证书由调用方按 certNewer 确定后传入（只取最近一张
599	// 或来自完整历史均可）：最近证书超差或到期时不会回退到更早的合格证书。
600	// 同一次核对的各部分必须共用同一个 today，避免跨午夜时判断不一致。
601	func decideUsage(inst *Instrument, latest *Certificate, today time.Time) *UsageDecision {
602		d := &UsageDecision{InstrumentID: inst.ID, evaluatedAt: today}
603		if inst.Status != StatusInUse {
604			d.Reasons = append(d.Reasons, fmt.Sprintf("器具当前状态为%s，只有在用器具可以申请使用", inst.Status))
605		}
606		if latest == nil {
607			d.Reasons = append(d.Reasons, "没有校准证书")
608		} else {
609			v := viewCertificate(*latest, inst.AllowedError, today)
610			d.Latest = &v
611			if !v.Pass {
612				d.Reasons = append(d.Reasons, fmt.Sprintf(
613					"最近证书 %s 测得误差绝对值 %g 超过允许误差 %g，判定超差",
614					latest.Number, math.Abs(latest.Error), inst.AllowedError))
615			}
616			if v.Expired {
617				d.Reasons = append(d.Reasons, fmt.Sprintf("最近证书 %s 已于 %s 到期（截止日当天即到期）",
618					latest.Number, latest.Expiry))
619			}
620		}
621		d.Allowed = len(d.Reasons) == 0
622		return d
623	}
624	
625	// evaluateAt 按器具状态与“最近证书”判定 now 所在本机日历日期能否使用。
626	// 只查询能否使用时只扫描挑出最近证书（latestCertificate），不整理完整历史。
627	func (l *Ledger) evaluateAt(id string, now time.Time) (*Instrument, *UsageDecision) {
628		inst := l.findInstrument(id)
629		if inst == nil {
630			return nil, nil
631		}
632		return inst, decideUsage(inst, l.latestCertificate(id), now)
633	}
634	
635	// CanUse 只按当前数据评估能否使用，不留存申请记录。
636	func (l *Ledger) CanUse(id string) (*UsageDecision, error) {
637		inst, d := l.evaluateAt(id, l.now())
638		if inst == nil {
639			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
640		}
641		return d, nil
642	}
643	
644	// cloneReasons 返回原因切片的独立副本，使对外返回的数据与台账内部存储
645	// 不共享底层数组：调用方替换、删减或补充返回结果中的原因，不会改写
646	// 已留痕的历史原因。nil 保持 nil，以维持空结果的既有表现。
647	func cloneReasons(in []string) []string {
648		if in == nil {
649			return nil
650		}
651		return append([]string(nil), in...)
652	}
653	
654	// RequestUse 针对已有器具提交使用申请：无论允许或拒绝都保存申请时间、结果
655	// 与当时全部原因。未知编号报错且不新增记录。
656	//
657	// 只有本次记录保存成功，申请才算提交完成：若台账文件无法写入或替换，明确返回
658	// 保存错误而不返回评估结果，台账（含同一对象随后的全部使用记录与按器具核对中
659	// 的被拒绝记录）与申请前完全一致——本次申请的时间、允许结果与拒绝原因不进入
660	// 历史，也不会在此后其他成功操作写盘时被顺带写入；器具登记信息、证书与校准计划
661	// 不因这次失败发生变化。恢复可写后无需重新打开台账，在同一台账重新申请才会按
662	// 当时的器具状态与证书重新判断并新增一条记录。
663	func (l *Ledger) RequestUse(id string) (*UsageDecision, error) {
664		if strings.TrimSpace(id) == "" {
665			return nil, fmt.Errorf("器具编号无效：%w", validationError("不能留空或只有空白"))
666		}
667		inst, d := l.evaluateAt(id, l.now())
668		if inst == nil {
669			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
670		}
671		// 留痕使用独立副本：返回给调用方的 d.Reasons 与其后的整理操作
672		// 不能成为改写台账内历史原因的途径。
673		rec := UsageRecord{
674			InstrumentID: id,
675			RequestedAt:  d.evaluatedAt.Format(time.RFC3339),
676			Allowed:      d.Allowed,
677			Reasons:      cloneReasons(d.Reasons),
678		}
679		if rec.Reasons == nil {
680			rec.Reasons = []string{}
681		}
682		// 在独立的新切片上暂存本次申请：只有原子替换台账文件成功后才提交。
683		// 写盘失败时恢复原切片，保证同一台账对象随后看到的全部使用记录与
684		// 按器具核对中的被拒绝记录都与申请前一致，失败申请也不会被之后的
685		// 写盘顺带写入。
686		original := l.data.Usage
687		staged := make([]UsageRecord, 0, len(original)+1)
688		staged = append(staged, original...)
689		staged = append(staged, rec)
690		l.data.Usage = staged
691		if err := l.save(); err != nil {
692			l.data.Usage = original
693			return nil, err
694		}
695		return d, nil
696	}
697	
698	// InstrumentReview 是按器具核对的完整视图。
699	type InstrumentReview struct {
700		Instrument Instrument        `json:"instrument"`
701		CanUse     bool              `json:"can_use"`
702		Reasons    []string          `json:"reasons"`
703		Latest     *CertificateView  `json:"latest"`
704		History    []CertificateView `json:"history"`
705		Rejections []UsageRecord     `json:"rejections"`
706		Plans      []PlanView        `json:"plans"`
707	}
708	
709	// Review 按器具核对：登记信息、当前能否使用及原因、最近证书与到期日、
710	// 全部历史证书、被拒绝的使用记录以及该器具当前与已结束的校准计划。
711	// 整份核对只采用核对开始时的一次本机日期：即使查询结束前跨过午夜，
712	// 能否使用、最近证书、历史证书到期判断与未结束计划标记也不会各自变成新一天。
713	// 历史拒绝原因按申请当时的冻结内容展示，不随本次采用的日期重新计算。
714	// 返回的证书、拒绝记录与计划（含改期历史）都是独立展示副本，调用方的
715	// 整理不回写台账，也不影响此前或之后分别取得的其他结果。
716	func (l *Ledger) Review(id string) (*InstrumentReview, error) {
717		// 本次核对只在开始时取一次本机时间，整份结果共用，跨午夜不分裂判断；
718		// 下一次核对会重新取当时的本机日期，不沿用本次结果。
719		now := l.now()
720		inst := l.findInstrument(id)
721		if inst == nil {
722			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
723		}
724		// 核对需要完整历史：该器具的证书只收集、排序这一次。历史视图与最近证书
725		// 都从同一份结果派生（最近证书即排序后的第一张），并共用同一个 today，
726		// 不再为最近证书单独整理一遍历史——也保证同一张证书在最近证书与历史中
727		// 编号、日期、误差、方法、摘要与到期判定完全一致，不会一边未到期一边到期。
728		certs := l.certificatesOf(id)
729		today := now
730		d := decideUsage(inst, latestOf(certs), today)
731		r := &InstrumentReview{
732			Instrument: *inst,
733			CanUse:     d.Allowed,
734			Reasons:    d.Reasons,
735			Latest:     d.Latest,
736		}
737		if r.Reasons == nil {
738			r.Reasons = []string{}
739		}
740		// 历史沿用既有空结果表现：没有证书时保持 nil（普通输出显示“无”，
741		// JSON 为 null）；有证书时按校准日期由近到远追加。
742		for _, c := range certs {
743			r.History = append(r.History, viewCertificate(c, inst.AllowedError, today))
744		}
745		for _, u := range l.data.Usage {
746			if u.InstrumentID == id && !u.Allowed {
747				// 逐条深拷贝原因：对外核对视图中的历史拒绝记录只是展示副本，
748				// 调用方的整理不能回写台账，也不能影响其他入口已取得的结果。
749				u.Reasons = cloneReasons(u.Reasons)
750				r.Rejections = append(r.Rejections, u)
751			}
752		}
753		r.Plans = l.planViews(id, today)
754		return r, nil
755	}
756	
757	// Instruments 返回全部登记器具的副本，按编号排序。
758	func (l *Ledger) Instruments() []Instrument {
759		out := append([]Instrument(nil), l.data.Instruments...)
760		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
761		return out
762	}
763	
764	// UsageRecords 返回全部使用申请记录，按申请发生的实际时刻从早到晚排序。
765	//
766	// RequestedAt 是带偏移的 RFC3339 时间：同一份台账可保存于不同系统时区偏移
767	// （含 Z 与显式零偏移），排序时换算为同一基准下的绝对时刻，因此显示文字里
768	// 小时、分钟更大的记录未必更晚，跨日记录也按实际时刻排列；记录各自保存时的
769	// 偏移决定先后，查询当天的系统时区不能改变历史顺序。获准与被拒绝的申请一起
770	// 参与排序，申请结果不作为排序条件。实际时刻相同的记录按器具编号升序；同一
771	// 器具在同一时刻的多次申请保留其在台账中的原有次序，每条已保存申请都保留、
772	// 不合并。没有记录时返回空结果，只有一条时原样返回。
773	//
774	// 返回的是展示副本：申请时间保留原文字及偏移，器具编号、申请结果与拒绝原因
775	// 保持保存时的内容；整理其中原因不会改动台账内已冻结的留痕，也不会被后续
776	// 正常写盘带入文件。查询本身不新增使用申请、不写回台账。
777	func (l *Ledger) UsageRecords() []UsageRecord {
778		out := append([]UsageRecord(nil), l.data.Usage...)
779		for i := range out {
780			out[i].Reasons = cloneReasons(out[i].Reasons)
781		}
782		sort.SliceStable(out, func(i, j int) bool {
783			// 时间能否识别、实际时刻比较与异常时间排列都走两处历史共用的
784			// compareHistoricalInstant；共同规则下并列（同一实际时刻，或两条
785			// 时间都无法识别且原文字相同）时，使用申请再按器具编号升序；编号
786			// 也相同的同一时刻多次申请由 SliceStable 保留其在台账中的原有次序，
787			// 不因获准/拒绝结果而变动。
788			if c := compareHistoricalInstant(out[i].RequestedAt, out[j].RequestedAt); c != 0 {
789				return c < 0
790			}
791			return out[i].InstrumentID < out[j].InstrumentID
792		})
793		return out
794	}
795

