	jan1early := time.Date(2027, 1, 1, 0, 0, 5, 0, time.Local)
	jan1day := time.Date(2027, 1, 1, 9, 30, 0, 0, time.Local)

	clock := &fakeClock{t: mustDate(t, "2026-12-01")}
	l := newTestLedger(t, clock)
