146		}
147		if len(p2.Changes) != 1 || p2.Changes[0].From != "2026-10-10" ||
148			p2.Changes[0].To != "2026-10-20" || p2.Changes[0].Reason != "实验室排期冲突" ||
149			p2.Changes[0].ChangedAt == "" {
150			t.Fatalf("改期记录不完整：%+v", p2.Changes)
151		}
152	}
