236		mustAddCert(t, l, CertificateInput{
237			InstrumentID: "M-2", Number: "C-OTHER", CalDate: "2026-10-02",
238			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
239		})
240		if _, _, err := l.CompletePlan("P-1", "C-OTHER"); !IsValidation(err) {
241			t.Fatalf("他器具证书应拒绝，得到 %v", err)
242		}
243		// 校准日期早于计划建立的本机日期。
244		mustAddCert(t, l, CertificateInput{
245			InstrumentID: "M-1", Number: "C-OLD", CalDate: "2026-10-01",
246			Expiry: "2027-10-01", Method: "m", Error: 0.1, Summary: "s",
247		})
248		if _, _, err := l.CompletePlan("P-1", "C-OLD"); !IsValidation(err) ||
249			!strings.Contains(err.Error(), "建立日期") {
250			t.Fatalf("早于计划建立日的证书应拒绝，得到 %v", err)
251		}
252		if l.findPlan("P-1").Status != PlanStatusOpen {
253			t.Fatal("失败的完成不应改动计划")
254		}
255	
256		// 符合条件：校准日期等于建立日期也可以。
257		mustAddCert(t, l, CertificateInput{
258			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
259			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
260		})
261		done, idem, err := l.CompletePlan("P-1", "C-1")
262		if err != nil || idem {
263			t.Fatalf("首次完成应成功且非幂等，err=%v idem=%v", err, idem)
264		}
265		if done.Status != PlanStatusDone || done.CompletedAt == "" || done.CertificateNumber != "C-1" {
266			t.Fatalf("完成信息不完整：%+v", done)
267		}
268	
269		// 时钟前进后再次用同一证书完成同一计划：返回原结果，不增加记录、不刷新时间。
270		clock.t = mustDate(t, "2026-10-05")
271		again, idem2, err := l.CompletePlan("P-1", "C-1")
272		if err != nil || !idem2 {
273			t.Fatalf("同证书重复完成应幂等成功，err=%v idem=%v", err, idem2)
274		}
275		if again.CompletedAt != done.CompletedAt {
276			t.Fatalf("重复完成刷新了完成时间：原 %s 现 %s", done.CompletedAt, again.CompletedAt)
277		}
278		if n := len(l.data.Plans); n != 1 {
279			t.Fatalf("重复完成增加了记录，共 %d 项计划", n)
280		}
281	
282		// 已完成计划改用另一证书：拒绝且保留原数据。
283		mustAddCert(t, l, CertificateInput{
284			InstrumentID: "M-1", Number: "C-2", CalDate: "2026-10-03",
285			Expiry: "2027-10-03", Method: "m", Error: 0.1, Summary: "s2",
286		})
287		if _, _, err := l.CompletePlan("P-1", "C-2"); !IsValidation(err) {
288			t.Fatalf("已完成计划换证书应拒绝，得到 %v", err)
289		}
290		if l.findPlan("P-1").CertificateNumber != "C-1" {
291			t.Fatal("拒绝换证书后原关联被改动")
292		}
293	
294		// 同一证书不能用于完成两项计划：M-2 的 P-2 用 C-OTHER 完成后，
295		// M-2 再建新计划也不能再用 C-OTHER。
296		clock.t = mustDate(t, "2026-10-02")
297		mustPlan(t, l, PlanInput{Number: "P-2", InstrumentID: "M-2", Date: "2026-10-10", Note: "二"})
298		if _, _, err := l.CompletePlan("P-2", "C-OTHER"); err != nil {
299			t.Fatalf("C-OTHER 应能完成 P-2：%v", err)
300		}
301		if _, _, err := l.CompletePlan("P-2", "C-1"); !IsValidation(err) {
302			t.Fatalf("他器具证书不能完成本器具计划，得到 %v", err)
303		}
304		mustPlan(t, l, PlanInput{Number: "P-3", InstrumentID: "M-2", Date: "2026-11-10", Note: "三"})
305		if _, _, err := l.CompletePlan("P-3", "C-OTHER"); !IsValidation(err) ||
306			!strings.Contains(err.Error(), "已用于完成计划") {
307			t.Fatalf("已用于完成其他计划的证书应拒绝再用，得到 %v", err)
308		}
309	}
