411		}
412		if fileExists(t, b) && readUsageCount(t, b) != 0 {
413			t.Fatal("留痕误入另一份台账 b")
414		}
415	}
416	
417	// 目标文件写入失败时报告目标路径并退出 2。
418	func TestTargetWriteFailureReported(t *testing.T) {
419		dir := chdirTemp(t)
420		// blocker 是普通文件，其下无法再创建目录与台账。
421		blocker := filepath.Join(dir, "blocker")
422		if err := os.WriteFile(blocker, []byte("x"), 0o644); err != nil {
423			t.Fatal(err)
424		}
425		target := filepath.Join(blocker, "ledger.json")
426		r := runArgs(t, "register", "--id", "M-1", "--name", "n",
427			"--allowed", "1", "-f", target)
428		if r.code != 2 {
429			t.Fatalf("写入失败应退出 2，得到 %d", r.code)
430		}
431		if !strings.Contains(r.stderr, target) {
432			t.Fatalf("应明确报告目标文件 %s，stderr=%q", target, r.stderr)
433		}
434	}
