474	
475	// 证书字段的值即使看起来是全局参数（--json、-f…、--file=…），也必须按文字
476	// 保存：不改变目标台账、不开启 JSON 输出，并能在随后核对与重开后完整查到。
477	func TestCertFieldValuesResemblingGlobalFlags(t *testing.T) {
478		dir := chdirTemp(t)
479		target := filepath.Join(dir, "真台账.json")
480		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
481			t.Fatal(r.stderr)
482		}
483	
484		// 摘要为 --json 且没有另行开启 JSON：录入成功并保持普通文字输出。
485		r := runArgs(t, certArgs(target, "C-1", "2026-09-01", "比较法", "--json")...)
486		if r.code != 0 {
487			t.Fatalf("摘要为 --json 应录入成功，code=%d stderr=%s", r.code, r.stderr)
488		}
489		if strings.HasPrefix(strings.TrimSpace(r.stdout), "{") {
490			t.Fatalf("未开启 --json 不应输出 JSON：%q", r.stdout)
491		}
492	
493		// 校准方法为 -f备用.json：仍写入真正指定的台账，不创建“备用.json”。
494		r = runArgs(t, certArgs(target, "C-2", "2026-09-02", "-f备用.json", "例行")...)
495		if r.code != 0 {
496			t.Fatalf("方法为 -f备用.json 应录入成功，code=%d stderr=%s", r.code, r.stderr)
497		}
498		// 校准方法为 --file=另一本.json：不参与台账选择，也不创建该文件。
499		r = runArgs(t, certArgs(target, "C-3", "2026-09-03", "--file=另一本.json", "等号形式")...)
500		if r.code != 0 {
501			t.Fatalf("方法为 --file=… 应录入成功，code=%d stderr=%s", r.code, r.stderr)
502		}
503		for _, stray := range []string{"备用.json", "另一本.json", "ledger.json"} {
504			if fileExists(t, filepath.Join(dir, stray)) {
505				t.Fatalf("字段值被误当成全局参数，产生了 %s", stray)
506			}
507		}
508	
509		// 按器具核对的 JSON 结果中完整查到这些文字；退出后重开同一台账保持一致。
510		want := map[string][2]string{
511			"C-1": {"比较法", "--json"},
512			"C-2": {"-f备用.json", "例行"},
513			"C-3": {"--file=另一本.json", "等号形式"},
514		}
515		for i := 0; i < 2; i++ {
516			rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
517			if rv.code != 0 {
518				t.Fatalf("review 失败 code=%d stderr=%s", rv.code, rv.stderr)
519			}
520			var view struct {
521				History []struct {
522					Number  string `json:"number"`
523					Method  string `json:"method"`
524					Summary string `json:"summary"`
525				} `json:"history"`
526			}
527			if err := json.Unmarshal([]byte(rv.stdout), &view); err != nil {
528				t.Fatalf("review JSON 解析失败: %v\n%s", err, rv.stdout)
529			}
530			got := map[string][2]string{}
531			for _, h := range view.History {
532				got[h.Number] = [2]string{h.Method, h.Summary}
533			}
534			for number, ms := range want {
535				if got[number] != ms {
536					t.Fatalf("第 %d 次核对 %s 内容不符：got=%v want=%v", i+1, number, got[number], ms)
537				}
538			}
539		}
540	}
541	
542	// 字段名与值分开传入、用等号连在一起传入，应得到相同的证书内容。
543	func TestCertSplitAndEqualsFormsMatch(t *testing.T) {
544		dir := chdirTemp(t)
545		target := filepath.Join(dir, "台账.json")
546		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
