581	// 需要值的证书参数放在命令末尾却没有值：明确报参数错误并退出 2，
582	// 不创建证书、不改动台账。
583	func TestCertTrailingFlagMissingValue(t *testing.T) {
584		dir := chdirTemp(t)
585		target := filepath.Join(dir, "台账.json")
586		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
587			t.Fatal(r.stderr)
